const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('latin1');
// Search for Everyday Crew Tee context
const idx = text.indexOf('Everyday Crew Tee');
if (idx >= 0) {
  // Print surrounding context
  const start = Math.max(0, idx - 500);
  const end = Math.min(text.length, idx + 1000);
  const snippet = text.substring(start, end);
  // Clean up non-printable chars
  console.log(snippet.replace(/[^\x20-\x7E\n\r\t]/g, ' '));
} else {
  console.log('Not found');
}
"

